from topics_a import t, T
F='fertility'
t('fertility',F,'fertility support',"Fertility support covers tests, advice and treatment for people trying to conceive, from first investigations to IVF and donor treatment.",["Both partners may need tests.","Age affects options.","Use HFEA data to compare clinics."])
t('fertility-clinic',F,'a fertility clinic',"Fertility clinics investigate causes of infertility and offer treatments such as IUI, IVF, ICSI, egg freezing and donor programmes.",["Check HFEA licensing and ratings.","Ask for a full costed plan.","Counselling must be offered."])
t('private-fertility-clinic',F,'a private fertility clinic',"Private fertility clinics offer self-funded treatment with shorter waits and more choice, alongside NHS-funded options in some areas.",["Compare clinics on HFEA data.","Ask about multi-cycle packages carefully.","Check what medication costs."])
t('fertility-assessment',F,'a fertility assessment',"A fertility assessment typically includes hormone blood tests, an ultrasound scan and semen analysis to understand your chances and options.",["Results guide the next steps.","Tests can be arranged quickly.","Ask for results to be explained."])
t('amh-test',F,'an AMH test',"An AMH (anti-Müllerian hormone) blood test gives an indication of ovarian reserve, helping plan fertility treatment.",["AMH does not predict natural conception on its own.","Results are best interpreted by a fertility specialist.","Combine with a scan for antral follicles."])
t('ovarian-reserve',F,'an ovarian reserve test',"Ovarian reserve testing uses AMH blood tests and antral follicle scans to estimate egg supply.",["Useful before egg freezing.","Not a fertility guarantee.","Discuss results with a specialist."])
t('semen-analysis',F,'semen analysis',"Semen analysis checks sperm count, movement and shape, usually as a first test of male fertility.",["Follow abstinence instructions.","One test may need repeating.","Results guide treatment choices."])
t('male-fertility-clinic',F,'a male fertility clinic',"Male fertility clinics investigate sperm problems and treat causes, with andrologists and urologists.",["Lifestyle factors affect sperm.","Surgical sperm retrieval is possible.","ICSI may be recommended."])
t('ivf',F,'IVF',"In vitro fertilisation (IVF) involves stimulating the ovaries, collecting eggs, fertilising them in the lab and transferring an embryo to the womb.",["Success rates depend strongly on age.","Single embryo transfer is safer.","Ask about storage for spare embryos."])
t('ivf-clinic',F,'an IVF clinic',"IVF clinics are HFEA-licensed centres offering IVF, often alongside ICSI, embryo freezing and donor treatment.",["Compare outcomes on the HFEA site.","Check monitoring locations.","Understand total costs."])
t('natural-ivf',F,'natural IVF',"Natural or mild IVF uses little or no stimulation medication, collecting one or a few eggs per cycle.",["Fewer eggs per cycle.","Lower medication use.","Suitability depends on your situation."])
t('icsi',F,'ICSI',"ICSI (intracytoplasmic sperm injection) injects a single sperm into each egg, often used for male factor infertility.",["Used alongside IVF.","Ask whether it is clinically needed.","Discuss success rates."])
t('iui',F,'IUI',"IUI (intrauterine insemination) places prepared sperm directly into the womb around ovulation, often for donor sperm or mild issues.",["Less invasive than IVF.","Success rates per cycle are lower.","Common with donor sperm."])
t('egg-freezing',F,'egg freezing',"Egg freezing involves ovarian stimulation and egg collection, then freezing eggs by vitrification for future use.",["Age at freezing affects success.","Storage rules allow up to 55 years with renewals.","Ask about likely numbers of eggs."])
t('egg-freezing-clinic',F,'an egg freezing clinic',"Egg freezing clinics are HFEA-licensed centres that collect and store eggs for future treatment.",["Check storage fees.","Ask about thaw survival rates.","Consent forms cover storage."])
t('embryo-freezing',F,'embryo freezing',"Embryo freezing stores embryos created through IVF for later transfer.",["Frozen transfers are common.","Both partners consent to storage.","Storage needs renewing."])
t('frozen-embryo-transfer',F,'a frozen embryo transfer',"A frozen embryo transfer (FET) thaws a stored embryo and transfers it to the womb in a natural or medicated cycle.",["Less medication than fresh IVF.","Timing is planned around your cycle.","Ask about success rates."])
t('donor-egg-clinic',F,'a donor egg clinic',"Donor egg clinics match recipients with egg donors and provide IVF using donated eggs.",["Donors in the UK can be identified by children at 18.","Counselling is important.","Waiting times vary."])
t('donor-eggs',F,'donor eggs',"Treatment with donor eggs uses eggs from another woman, fertilised and transferred to the intended mother or surrogate.",["Success rates reflect donor age.","Legal parenthood rules apply.","Implications counselling is recommended."])
t('donor-sperm',F,'donor sperm',"Donor sperm treatment uses sperm from a screened donor through IUI or IVF, for single women, same-sex couples and male infertility.",["UK donors are screened.","Donor-conceived people can access identifying information at 18.","Use HFEA-licensed clinics."])
A='aesthetics'
t('aesthetic-clinic',A,'an aesthetic clinic',"Aesthetic clinics offer non-surgical treatments such as anti-wrinkle injections, fillers, skin boosters and peels.",["Ask who prescribes and who treats.","Check premises standards.","Consultations should come first."],hub='cosmetic-clinics')
t('aesthetic-doctor',A,'an aesthetic doctor',"Aesthetic doctors are GMC-registered doctors who provide cosmetic injectables and skin treatments, with medical training to manage complications.",["Check GMC registration.","Ask about complication management.","Look for natural results."])
t('cosmetic-clinic',A,'a cosmetic clinic',"Cosmetic clinics provide aesthetic treatments and sometimes cosmetic surgery, so it is important to know which regulations apply.",["Surgical clinics must be CQC registered in England.","Non-surgical licensing is coming.","Read reviews critically."])
t('botox',A,'Botox-type anti-wrinkle injections',"Anti-wrinkle injections relax specific muscles to soften lines, using a prescription-only medicine that must be prescribed after a consultation.",["Effects usually last a few months.","A prescriber must assess you.","Choose experienced practitioners."])
t('botox-clinic',A,'a Botox clinic',"Clinics offering anti-wrinkle injections should have a prescriber assess you face to face and use licensed products.",["Ask the brand of product used.","Follow-up review is good practice.","Avoid treatment at parties."])
t('anti-wrinkle',A,'anti-wrinkle treatment',"Anti-wrinkle treatments include injections, skin boosters, peels and good skincare, chosen after assessing your skin.",["Combination plans often work best.","Sun protection is essential.","Set realistic expectations."])
t('fillers',A,'dermal fillers',"Dermal fillers, usually hyaluronic acid, restore volume or shape to lips, cheeks and other areas; they carry risks that need skilled practitioners.",["Hyaluronic fillers can be dissolved.","Vascular complications are rare but serious.","Ask about emergency protocols."])
t('dermal-fillers-clinic',A,'a dermal fillers clinic',"Dermal filler clinics should use CE or UKCA-marked products and practitioners trained in anatomy and complication management.",["Ask whether hyaluronidase is on site.","Check training credentials.","Avoid unbranded fillers."])
t('cheek-fillers',A,'cheek fillers',"Cheek fillers restore or enhance volume in the mid-face, which can lift and soften the overall appearance.",["Subtle volume often looks most natural.","Results last many months.","Bruising is possible."])
t('chemical-peel',A,'a chemical peel',"Chemical peels apply acids to remove damaged outer skin layers, improving texture, tone, acne and fine lines.",["Depth of peel affects downtime.","Sun protection afterwards is vital.","Skin type affects suitability."])
t('chemical-peel-clinic',A,'a chemical peel clinic',"Clinics offering peels should assess skin type, history and medication before choosing the right peel strength.",["Patch tests may be needed.","Deeper peels need medical supervision.","Follow aftercare carefully."])
S='cosmetic_surgery'
t('cosmetic-surgery',S,'cosmetic surgery',"Cosmetic surgery changes appearance through operations such as breast surgery, eyelid surgery, facelifts and body contouring.",["Choose a GMC specialist register surgeon.","Allow a cooling-off period.","Plan recovery properly."])
t('breast-augmentation',S,'breast augmentation',"Breast augmentation uses implants or fat transfer to increase breast size or improve shape.",["Implants may need replacing in future.","Implant details go on the Breast and Cosmetic Implant Registry.","Discuss size realistically."])
t('breast-lift',S,'a breast lift',"A breast lift (mastopexy) removes excess skin and reshapes breast tissue to raise the breasts.",["Scars fade but remain.","Can be combined with implants.","Future pregnancy can affect results."])
t('breast-reduction',S,'breast reduction',"Breast reduction surgery reduces breast size and weight, often to relieve back, neck and shoulder pain.",["NHS funding is limited.","Breastfeeding may be affected.","Recovery takes several weeks."])
t('blepharoplasty',S,'blepharoplasty (eyelid surgery)',"Blepharoplasty removes excess skin or fat from upper or lower eyelids, sometimes improving vision as well as appearance.",["Eye health is checked first.","Bruising settles over weeks.","Scars sit in natural creases."])
t('facelift',S,'a facelift',"A facelift tightens the lower face and neck by repositioning tissues and removing excess skin.",["Different techniques suit different faces.","Recovery takes several weeks.","Results age naturally."])
t('fue-hair-transplant',S,'an FUE hair transplant',"FUE hair transplants move individual follicles from a donor area to thinning areas, performed under local anaesthetic.",["The surgeon should be involved, not just technicians.","Clinics must be CQC registered in England.","Results take months to appear."])
